def sudoku_valid(board: list[list[int]]) -> bool:
    # Validate dimensions
    if not isinstance(board, list) or len(board) != 9:
        raise ValueError("Board must be a 9x9 list.")

    for row in board:
        if not isinstance(row, list) or len(row) != 9:
            raise ValueError("Board must be a 9x9 list.")
        for val in row:
            if not isinstance(val, int) or isinstance(val, bool) or val < 0 or val > 9:
                raise ValueError("All values must be integers between 0 and 9.")

    # Check rows, columns, and 3x3 boxes
    rows = [set() for _ in range(9)]
    cols = [set() for _ in range(9)]
    boxes = [set() for _ in range(9)]

    for r in range(9):
        for c in range(9):
            val = board[r][c]
            if val == 0:
                continue

            box_idx = (r // 3) * 3 + (c // 3)

            if val in rows[r] or val in cols[c] or val in boxes[box_idx]:
                return False

            rows[r].add(val)
            cols[c].add(val)
            boxes[box_idx].add(val)

    return True
